--
-- Table structure for table `trips`
--

DROP TABLE IF EXISTS `trips`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `trips` (
  `ID` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID (séquence incrémentale)',
  `DEDATED` datetime DEFAULT NULL COMMENT 'Date du voyage',
  `TRIP_ID` bigint DEFAULT NULL COMMENT 'Identifiant du voyage dans la journée',
  `DENUMLI` bigint DEFAULT NULL COMMENT 'Numéro de ligne (FK DRLIGNE)',
  `SERVICE_ID` bigint DEFAULT NULL COMMENT 'Identifiant du service',
  `DIRECTION_ID` bigint DEFAULT NULL COMMENT 'Direction (0=aller, 1=retour)',
  `TIME_DEPART` datetime DEFAULT NULL COMMENT 'Heure de départ prévue',
  `HAVERET` bigint DEFAULT NULL COMMENT 'A un voyage retour lié (0=non, 1=oui)',
  `TIME_NRET` datetime DEFAULT NULL COMMENT 'Heure du retour',
  `TRIP_NID` double DEFAULT NULL COMMENT 'ID du voyage retour lié',
  `GRP` bigint DEFAULT NULL COMMENT 'Groupe de voyages',
  `BUS_PR` bigint DEFAULT NULL COMMENT 'Bus prévu (code véhicule FK DRVEHIC)',
  `BUS_RE` bigint DEFAULT NULL COMMENT 'Bus réel (code véhicule)',
  `CHAUFF_PR` bigint DEFAULT NULL COMMENT 'Chauffeur prévu (code agent FK DRAGENT)',
  `CHAUFF_RE` bigint DEFAULT NULL COMMENT 'Chauffeur réel (code agent)',
  `REC_PR` bigint DEFAULT NULL COMMENT 'Receveur prévu (code agent)',
  `REC_RE` bigint DEFAULT NULL COMMENT 'Receveur réel (code agent)',
  `ETAT` bigint DEFAULT NULL COMMENT 'État du voyage (3=terminé, 5=autre)',
  `TIME_DEPART_R` datetime DEFAULT NULL COMMENT 'Heure de départ réelle',
  `TIME_ARRIVE_R` datetime DEFAULT NULL COMMENT 'Heure d''arrivée réelle',
  `VMAX` double DEFAULT NULL COMMENT 'Vitesse maximale enregistrée (km/h)',
  `AVANCE_RETARD` bigint DEFAULT NULL COMMENT 'Écart en secondes (>0=retard, <0=avance)',
  `CHANGEMENT` bigint DEFAULT NULL COMMENT 'Indicateur de changement',
  `META_DATA` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'JSON: stop_time_nbr, lastLat, lastLon, km',
  `DEVALID` bigint DEFAULT NULL COMMENT 'Indicateur de validation',
  `ALERT` bigint DEFAULT NULL COMMENT 'Indicateur d''alerte',
  PRIMARY KEY (`ID`),
  KEY `IDX_TRIPS_DENUMLI` (`DENUMLI`),
  KEY `IDX_TRIPS_BUS_PR` (`BUS_PR`),
  KEY `IDX_TRIPS_CHAUFF_PR` (`CHAUFF_PR`),
  CONSTRAINT `FK_TRIPS_DRAGENT` FOREIGN KEY (`CHAUFF_PR`) REFERENCES `dragent` (`DECAGEN`),
  CONSTRAINT `FK_TRIPS_DRLIGNE` FOREIGN KEY (`DENUMLI`) REFERENCES `drligne` (`DENUMLI`),
  CONSTRAINT `FK_TRIPS_DRVEHIC` FOREIGN KEY (`BUS_PR`) REFERENCES `drvehic` (`DECODVH`)
) ENGINE=InnoDB AUTO_INCREMENT=83507 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
